import type { Design } from "./schema.ts";

export interface ThemeEntry {
  /** Folder name; "default" for the root DESIGN.md. */
  name: string;
  design: Design;
}

const HEADER = `/*
 * AUTO-GENERATED by @dashboard-kit/tokens from DESIGN.md (and themes/<name>/DESIGN.md).
 * Do not edit — change the DESIGN.md files instead.
 */`;

const block = (selector: string, vars: Record<string, string>) =>
  `${selector} {\n${Object.entries(vars)
    .map(([name, value]) => `  --${name}: ${value};`)
    .join("\n")}\n}`;

/**
 * Runtime variables for one theme. Everything that can differ between
 * themes is a runtime variable, so switching theme never needs a rebuild.
 */
export function lightVars(design: Design): Record<string, string> {
  const vars: Record<string, string> = { radius: design.radius, ...design.colors.light };

  vars["dk-font-sans"] = design.typography.sans;
  vars["dk-font-heading"] = design.typography.heading;
  vars["dk-font-mono"] = design.typography.mono;

  if (design.density) vars["dk-spacing"] = design.density.spacing;

  for (const [size, value] of Object.entries(design.shadows ?? {})) {
    if (value) vars[`dk-shadow-${size}`] = value;
  }
  for (const [size, value] of Object.entries(design.fontSizes ?? {})) {
    if (!value) continue;
    if (typeof value === "string") {
      vars[`dk-text-${size}`] = value;
    } else {
      vars[`dk-text-${size}`] = value.size;
      vars[`dk-text-${size}-lh`] = value.lineHeight;
    }
  }
  for (const [name, value] of Object.entries(design.motion?.duration ?? {})) vars[`duration-${name}`] = value;
  for (const [name, value] of Object.entries(design.motion?.ease ?? {})) vars[`dk-ease-${name}`] = value;

  return vars;
}

/** Maps Tailwind's theme namespaces onto the runtime variables (from the default theme's token set). */
export function themeInlineVars(design: Design): Record<string, string> {
  const vars: Record<string, string> = {};
  for (const name of Object.keys(design.colors.light)) vars[`color-${name}`] = `var(--${name})`;

  vars["radius-sm"] = "calc(var(--radius) - 4px)";
  vars["radius-md"] = "calc(var(--radius) - 2px)";
  vars["radius-lg"] = "var(--radius)";
  vars["radius-xl"] = "calc(var(--radius) + 4px)";

  vars["font-sans"] = "var(--dk-font-sans)";
  vars["font-heading"] = "var(--dk-font-heading)";
  vars["font-mono"] = "var(--dk-font-mono)";

  if (design.density) vars["spacing"] = "var(--dk-spacing)";

  for (const [size, value] of Object.entries(design.shadows ?? {})) {
    if (value) vars[`shadow-${size}`] = `var(--dk-shadow-${size})`;
  }
  for (const [size, value] of Object.entries(design.fontSizes ?? {})) {
    if (!value) continue;
    vars[`text-${size}`] = `var(--dk-text-${size})`;
    if (typeof value !== "string") vars[`text-${size}--line-height`] = `var(--dk-text-${size}-lh)`;
  }
  for (const name of Object.keys(design.motion?.ease ?? {})) vars[`ease-${name}`] = `var(--dk-ease-${name})`;

  return vars;
}

export function selectorsFor(name: string) {
  return name === "default"
    ? { light: ":root", dark: ".dark" }
    : { light: `:root[data-theme="${name}"]`, dark: `:root[data-theme="${name}"].dark` };
}

/** CSS for one theme's variables (no Tailwind mapping). */
export function compileThemeBlocks({ name, design }: ThemeEntry): string {
  const selectors = selectorsFor(name);
  return [
    `/* Theme: ${design.meta.name} (${name}) v${design.meta.version} */`,
    block(selectors.light, lightVars(design)),
    block(selectors.dark, design.colors.dark),
  ].join("\n");
}

/** Default theme + Tailwind mapping. Enough on its own; other themes can be loaded lazily. */
export function compileBaseCss(defaultTheme: ThemeEntry): string {
  return [HEADER, compileThemeBlocks(defaultTheme), block("@theme inline", themeInlineVars(defaultTheme.design))].join(
    "\n\n",
  ) + "\n";
}

/** Everything in one file: base + every tenant theme. */
export function compileAllCss(themes: ThemeEntry[]): string {
  const [defaultTheme, ...others] = themes;
  if (!defaultTheme) throw new Error("No default theme");
  return [compileBaseCss(defaultTheme).trimEnd(), ...others.map(compileThemeBlocks)].join("\n\n") + "\n";
}

/** Values for JavaScript (charts, theme pickers). */
export function compileJson(themes: ThemeEntry[]): string {
  return (
    JSON.stringify(
      {
        default: "default",
        list: themes.map(({ name, design }) => ({
          name,
          label: design.meta.name,
          description: design.meta.description ?? "",
          version: design.meta.version,
        })),
        themes: Object.fromEntries(themes.map(({ name, design }) => [name, design])),
      },
      null,
      2,
    ) + "\n"
  );
}
